fn is_prime(n: i8) -> bool {
    // By definition in the prompt, primes are integers >= 2.
    if n < 2 {
        return false;
    }

    // For i8, n is at most 127, so trial division up to n-1 is cheap.
    // We iterate candidate divisors k in increasing order: 2 <= k < n.
    let mut k: i16 = 2;
    let n16: i16 = n as i16;

    while k < n16 {
        // If k divides n, then n is not prime.
        if n16 % k == 0 {
            return false;
        }

        // Termination measure example: (n - k) decreases by 1 each iteration.
        k += 1;
    }

    // No divisor found in [2, n), so n is prime under the given definition.
    true
}